import{_ as t,o,c as a,ae as r}from"./chunks/framework.BvHJbMD4.js";const p=JSON.parse('{"title":"The Concept: The Horten Mystery","description":"","frontmatter":{},"headers":[],"relativePath":"en/konzept.md","filePath":"en/konzept.md"}'),i={name:"en/konzept.md"};function h(n,e,s,l,c,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="the-concept-the-horten-mystery" tabindex="-1">The Concept: The Horten Mystery <a class="header-anchor" href="#the-concept-the-horten-mystery" aria-label="Permalink to &quot;The Concept: The Horten Mystery&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Horten Mystery: A Fabulous Fiction of Power, Money, and Pearls</em></p><h2 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h2><p>This mockumentary is a satirical and at the same time profound examination of the legacy of one of the richest and most controversial couples in German-Austrian history: Heidi and Helmut Horten.</p><p>We combine historical facts with fictional elements to show the absurdity of extreme wealth, the mechanisms of displacement, and the intertwining of capital and politics.</p><h2 id="the-structure-4-parts" tabindex="-1">The Structure (4 Parts) <a class="header-anchor" href="#the-structure-4-parts" aria-label="Permalink to &quot;The Structure (4 Parts)&quot;">​</a></h2><h3 id="_1-the-dazzling-widow" tabindex="-1">1. The Dazzling Widow <a class="header-anchor" href="#_1-the-dazzling-widow" aria-label="Permalink to &quot;1. The Dazzling Widow&quot;">​</a></h3><p>A look at Heidi&#39;s life after her husband&#39;s death. We show her eccentric luxury, her art collection, and her role as the &quot;Grande Dame&quot; of society.</p><h3 id="_2-the-rise-of-helmut-horten" tabindex="-1">2. The Rise of Helmut Horten <a class="header-anchor" href="#_2-the-rise-of-helmut-horten" aria-label="Permalink to &quot;2. The Rise of Helmut Horten&quot;">​</a></h3><p>We document Helmut&#39;s path to becoming the &quot;department store king.&quot; The focus here is on the &quot;market consolidation&quot; (Aryanization) of the 1930s.</p><h3 id="_3-the-fate-of-the-losers" tabindex="-1">3. The Fate of the Losers <a class="header-anchor" href="#_3-the-fate-of-the-losers" aria-label="Permalink to &quot;3. The Fate of the Losers&quot;">​</a></h3><p>What happened to those who had to give up their department stores? We highlight the fate of the Alsberg brothers and other victims.</p><h3 id="_4-the-political-love-story" tabindex="-1">4. The Political Love Story <a class="header-anchor" href="#_4-the-political-love-story" aria-label="Permalink to &quot;4. The Political Love Story&quot;">​</a></h3><p>The relationship with the Austrian People&#39;s Party (ÖVP). We dedicate ourselves to the &quot;Rain of Gold&quot; – the donations and the systematic splitting of payments.</p><hr><p><em>This project is a balancing act between documentation and satire.</em></p>',16)])])}const m=t(i,[["render",h]]);export{p as __pageData,m as default};
